#include "ui/desktop_music.hpp"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <QEventLoop>
#include <QElapsedTimer>
#include <iostream>
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{auto require=[](bool ok,const char* why){if(!ok)throw std::runtime_error(why);};require(argc==2,"Source root argument");QString source=QString::fromLocal8Bit(argv[1]);QTemporaryDir temp;require(temp.isValid(),"Temp root");auto root=temp.path();QDir().mkpath(root+"/assets/audio");for(const auto& name:QStringList{"mevison-background.wav","mevison-cover.ico","after-deal-perekyp.mp3","after-deal-perekyp-cover.jpg"})require(QFile::copy(source+"/assets/audio/"+name,root+"/assets/audio/"+name),"Copy audio fixtures");auto wait=[](std::function<bool()> predicate){QElapsedTimer t;t.start();while(!predicate()&&t.elapsed()<6000){QEventLoop l;QTimer::singleShot(25,&l,&QEventLoop::quit);l.exec();}return predicate();};DesktopMusic music;music.initialize(root,QJsonObject{{"folders",QJsonArray()}});require(wait([&]{return !music.scanning()&&music.duration()>60000;}),"Mevison loads");require(music.current().artist=="Perekyp.ru"&&!music.cover().isNull(),"Mevison application icon and corrected artist");require(music.tracks().size()==2&&music.current().title=="Mevison"&&music.tracks()[1].title==QStringLiteral("После сделки"),"Two correctly named builtins without user folders");require(music.addFolder(root+"/assets/audio"),"Add built-in folder as user folder");require(wait([&]{return !music.scanning();}),"Rescan finishes");require(music.tracks().size()==2,"Builtins not duplicated by folder scan");music.next();require(wait([&]{return music.index()==1&&music.duration()>129000&&music.duration()<131000;}),"Actual supplied MP3 decodes as 129 seconds");require(music.current().builtin&&music.current().artist=="PEREKYP.RU"&&!music.cover().isNull(),"New song has artist and cover");music.removeFolder(root+"/assets/audio");require(wait([&]{return !music.scanning();}),"Remove folder scan");require(music.tracks().size()==2&&music.index()==1,"Rescan retains both builtins and selection");auto saved=music.snapshot();DesktopMusic restored;restored.initialize(root,saved);require(wait([&]{return !restored.scanning()&&restored.index()==1&&restored.duration()>129000;}),"Saved new-track selection survives restart");DesktopMusic migrated;migrated.initialize(root,QJsonObject{{"folders",QJsonArray()},{"current",QUrl::fromLocalFile(root+"/assets/audio/mevison-background.wav").toString()},{"position",12000}});require(wait([&]{return !migrated.scanning()&&migrated.index()==0&&std::abs(migrated.position()-12000)<500;}),"Old Mevison selection and position preserved");require(migrated.current().title=="Mevison"&&migrated.tracks().size()==2,"Old V8.5 preferences migrate without renaming old audio");DesktopMusic moved;moved.initialize(root,QJsonObject{{"folders",QJsonArray{QString("/old-game/Music")}},{"current",QUrl::fromLocalFile("/old-game/assets/audio/after-deal-perekyp.mp3").toString()}});require(wait([&]{return !moved.scanning()&&moved.index()==1;}),"Moving game folder preserves bundled selection");require(moved.folders().contains(root+"/Music"),"Default Music path relocates with game");std::cout<<"PASS bundled music: two tracks, original Mevison, supplied MP3/cover/duration, no duplicates, rescan/reload and old preferences\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
